2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Function;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Every domain table, child-before-parent. Referential integrity is dropped around the
34	     * TRUNCATE so the order is only for readability of the FK chain (invoices -> projects ->
35	     * clients). Add a new table here (and a matching {@code seedTable} call) to extend the harness.
36	     */
37	    private static final List<String> TABLES =
38	            List.of("invoice_line_items", "invoices", "tasks", "contacts", "projects", "clients");
39	
40	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
41	    @PostMapping("/reset")
42	    public void reset() {
43	        audit.clear();
44	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
45	        for (String table : TABLES) {
46	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
47	        }
48	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	    }
50	
51	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
52	    @PostMapping("/seed")
53	    public void seed(@RequestBody Map<String, Object> fixture) {
54	        seedTable(fixture, "clients", "INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
55	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email")});
56	        seedTable(fixture, "projects", "INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
57	                p -> new Object[] {id(p, "id"), p.get("name"), id(p, "clientId")});
58	        seedTable(fixture, "contacts",
59	                "INSERT INTO contacts (id, name, email, role, client_id) VALUES (?, ?, ?, ?, ?)",
60	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email"), c.get("role"),
61	                        id(c, "clientId")});
62	        seedTable(fixture, "tasks", "INSERT INTO tasks (id, title, done, project_id) VALUES (?, ?, ?, ?)",
63	                t -> new Object[] {id(t, "id"), t.get("title"), Boolean.TRUE.equals(t.get("done")),
64	                        id(t, "projectId")});
65	        seedInvoices(fixture);
66	    }
67	
68	    /**
69	     * Seed invoices and, nested under each, its line items. An invoice's amount is the sum of its
70	     * lines' qty * unitPrice, so when a fixture lists {@code lineItems} the amount is derived from
71	     * them (the user no longer types one figure); a fixture may still give an explicit
72	     * {@code amount} instead (an invoice with no lines). One method rather than a plain seedTable
73	     * call because the line items live inside each invoice, keyed by the invoice's own id.
74	     */
75	    @SuppressWarnings("unchecked")
76	    private void seedInvoices(Map<String, Object> fixture) {
77	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
78	        if (invoices == null) {
79	            return;
80	        }
81	        for (Map<String, Object> invoice : invoices) {
82	            long invoiceId = id(invoice, "id");
83	            List<Map<String, Object>> lineItems =
84	                    (List<Map<String, Object>>) invoice.get("lineItems");
85	            double amount;
86	            if (invoice.get("amount") != null) {
87	                amount = ((Number) invoice.get("amount")).doubleValue();
88	            } else {
89	                amount = 0.0;
90	                if (lineItems != null) {
91	                    for (Map<String, Object> line : lineItems) {
92	                        amount += ((Number) line.get("qty")).doubleValue()
93	                                * ((Number) line.get("unitPrice")).doubleValue();
94	                    }
95	                }
96	            }
97	            jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
98	                    + " VALUES (?, ?, ?, ?, ?, ?)",
99	                    invoiceId, id(invoice, "projectId"), amount,
100	                    invoice.getOrDefault("status", "DRAFT"), invoice.get("issuedDate"),
101	                    invoice.get("dueDate"));
102	            if (lineItems != null) {
103	                for (Map<String, Object> line : lineItems) {
104	                    jdbc.update("INSERT INTO invoice_line_items"
105	                            + " (id, invoice_id, description, qty, unit_price) VALUES (?, ?, ?, ?, ?)",
